<template><AppLayout page-title="Marketplace"><div class="card" style="margin-bottom:16px"><div class="searchbar"><input class="input" v-model="query" @keyup.enter="searchProducts" placeholder="Rechercher un médicament…"><button class="btn btn-primary" @click="searchProducts">Rechercher</button></div></div><div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div class="product-grid"><div v-for="p in products" :key="p.product_id" class="card product"><div class="product-head"><div><h3>{{p.product_name}}</h3><small>{{p.brand||p.generic_name||p.form+' '+p.dosage}}</small></div><span class="badge" :class="p.is_prescription_required?'badge-amber':'badge-green'">{{p.is_prescription_required?'Ordonnance':'Libre'}}</span></div><p>{{p.pharmacy_name}} · {{p.pharmacy_city}}</p><strong>{{Number(p.price).toLocaleString('fr-FR')}} {{p.currency}}</strong><small>Stock : {{p.current_stock}}</small><button class="btn btn-primary btn-sm" :disabled="!p.current_stock" @click="add(p)">Ajouter au panier</button></div></div><div v-if="!loading&&!products.length" class="empty-state">Aucun produit trouvé.</div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useCartStore} from '@/stores/cart';const cart=useCartStore(),query=ref(''),products=ref<any[]>([]),loading=ref(false);async function searchProducts(){loading.value=true;const {data,error}=await supabase.rpc('search_marketplace',{p_query:query.value||null,p_in_stock_only:true,p_sort_by:'name',p_limit:50,p_offset:0});products.value=error?[]:data||[];loading.value=false}async function add(p:any){await cart.addItem(p.product_id,p.pharmacy_id,Number(p.price),1)}onMounted(searchProducts)</script>
